        assertTrue(result.changes.any { it.ruleId == "struct-legacy-capability-facade-lookup" })
        assertTrue(result.changes.any { it.ruleId == "struct-legacy-capability-attachment-bridge" })
        assertTrue(result.changes.any { it.ruleId == "struct-legacy-capability-attachment-register" })
        assertTrue(result.changes.any { it.ruleId == "struct-legacy-capability-data-attachment-serializable" })
        assertTrue(result.changes.any { it.ruleId == "struct-legacy-capability-attachment-main-register" })
        assertTrue(facade.contains("final class CleanlinessBridge"), facade)
        assertFalse(facade.contains("public final class CleanlinessBridge"), facade)
        assertTrue(facade.contains("LazyOptional<CleanlinessState> get(Player player)"), facade)
        assertTrue(facade.contains("player.getData(CleanlinessBridgeAttachment.CLEAN_STATE)"), facade)
        assertFalse(facade.contains("Dirtiness"), facade)
        assertFalse(facade.contains("WrongFacadeFile"), facade)
        assertTrue(attachment.contains("public final class CleanlinessBridgeAttachment"), attachment)
        assertTrue(attachment.contains("Supplier<AttachmentType<CleanlinessState>> CLEAN_STATE"), attachment)
        assertTrue(attachment.contains("ATTACHMENT_TYPES.register(\"clean_state\", () -> AttachmentType.serializable(CleanlinessState::new).copyOnDeath().build())"), attachment)
        assertFalse(attachment.contains("Dirtiness"), attachment)
        assertTrue(data.contains("class CleanlinessState implements INBTSerializable<CompoundTag>"), data)
        assertTrue(data.contains("serializeNBT(HolderLookup.Provider provider)"), data)
        assertTrue(data.contains("deserializeNBT(HolderLookup.Provider provider, CompoundTag tag)"), data)
        assertTrue(mod.contains("CleanlinessBridgeAttachment.register(modEventBus);"), mod)
        assertFalse(mod.contains("DirtinessAttachment"), mod)
        assertTrue(use.contains("CleanlinessBridge.get(player).ifPresent(CleanlinessState::reset);"), use)
        assertTrue(use.contains("CleanlinessBridge.get(player).ifPresent(state -> {"), use)
        assertFalse(use.contains("getCapability(CleanlinessBridge.CLEAN_STATE"), use)
    }

    @Test
    fun `INBTSerializable holder lookup migration is scoped to executable serializable types`() {
        val projectDir = createFile("NbtSerializableSurface.java", """
            package com.example;

            import net.minecraft.nbt.CompoundTag;
            import net.neoforged.neoforge.common.util.INBTSerializable;

            public class NbtSerializableSurface implements INBTSerializable<CompoundTag> {
                private static final String DOC = "public CompoundTag serializeNBT() public void deserializeNBT(CompoundTag tag)";

                /*
                public CompoundTag serializeNBT() {
                    return new CompoundTag();
                }

                public void deserializeNBT(CompoundTag tag) {
                }
                */
                @Override
                public CompoundTag serializeNBT() {
                    return new CompoundTag();
                }

                @Override
                public void deserializeNBT(CompoundTag tag) {
                }
            }

            class DocumentationOnly {
                public CompoundTag serializeNBT() {
                    return new CompoundTag();
                }

                public void deserializeNBT(CompoundTag tag) {
                }
            }
        """.trimIndent())

        val result = StructuralRefactorPass().apply(projectDir)
        val migrated = tempDir.resolve("src/main/java/com/example/NbtSerializableSurface.java").readText()

        assertTrue(result.changes.any { it.ruleId == "struct-inbtserializable-holderlookup" })
        assertTrue(migrated.contains("""private static final String DOC = "public CompoundTag serializeNBT() public void deserializeNBT(CompoundTag tag)";"""), migrated)
        assertTrue(migrated.contains("public CompoundTag serializeNBT(net.minecraft.core.HolderLookup.Provider provider)"), migrated)
        assertTrue(migrated.contains("public void deserializeNBT(net.minecraft.core.HolderLookup.Provider provider, CompoundTag tag)"), migrated)
        val commentBlock = migrated.substringAfter("/*").substringBefore("*/")
        assertTrue(commentBlock.contains("public CompoundTag serializeNBT()"), migrated)
        assertTrue(commentBlock.contains("public void deserializeNBT(CompoundTag tag)"), migrated)
        val documentationOnly = migrated.substringAfter("class DocumentationOnly")
        assertTrue(documentationOnly.contains("public CompoundTag serializeNBT()"), migrated)
        assertTrue(documentationOnly.contains("public void deserializeNBT(CompoundTag tag)"), migrated)
        assertFalse(documentationOnly.contains("HolderLookup.Provider"), migrated)
    }

