        assertTrue(packet.contains("CustomPacketPayload.Type<LocalDataSyncPacket> TYPE"), packet)
        assertFalse(packet.contains("getAttachment()"), packet)
        assertFalse(packet.contains("LocalAttachments.LOCAL_DATA"), packet)
    }

