                }
            }
        """.trimIndent())
        srcDir.resolve("IronLadderBlock.java").writeText("""
            package com.example;

            import net.minecraft.world.level.block.LadderBlock;

            public class IronLadderBlock extends LadderBlock {
                public IronLadderBlock(Properties properties) {
                    super(properties);
                }
