    @Test
    fun `migrates legacy living tick events and removes split tick phase checks`() {
        val projectDir = createFile("TickHandlers.java", """
            package com.example;

            import net.minecraft.server.level.ServerPlayer;
            import net.minecraft.world.entity.LivingEntity;
            import net.neoforged.bus.api.SubscribeEvent;
            import net.neoforged.fml.LogicalSide;
            import net.neoforged.neoforge.client.event.ClientTickEvent;
            import net.neoforged.neoforge.event.entity.living.LivingEvent;
            import net.neoforged.neoforge.event.tick.LevelTickEvent;

            public class TickHandlers {
                private static int pending;
                private static final String SIDE_DOC = "event.side == LogicalSide.SERVER";

                @SubscribeEvent
                public static void onLivingTick(LivingEvent.LivingTickEvent event) {
                    if (event.getEntity().level().isClientSide()) return;
                    LivingEntity entity = event.getEntity();
                    use(entity);
                }

                @SubscribeEvent
                public static void onCancelableLivingTick(LivingEvent.LivingTickEvent event) {
                    LivingEntity entity = event.getEntity();
                    if (!event.isCanceled()) {
                        use(entity);
                    }
                }

                @SubscribeEvent
                public static void onPlayerTick(LivingEvent.LivingTickEvent event) {
                    if (!(event.getEntity() instanceof ServerPlayer player)) return;
                    String playerTickDoc = "scheduler.tick(player);";
                    String playerTickBlock = ${"\"\"\""}
                        scheduler.tick(player);
                        ${"\"\"\""};
                    // scheduler.tick(player);
                    scheduler.tick(player);
                    use(player);
                }

                @SubscribeEvent
                public static void onClientTick(ClientTickEvent.Post event) {
                    // [forge2neo] TickEvent.Phase.END guard removed
                    // phase check removed in NeoForge
                    if (event.phase == TickEvent.Phase.END) {
                        ping();
                    }
                    if (event.phase != TickEvent.Phase.END || pending <= 0) {
                        return;
                    }
                    pending--;
                }

                @SubscribeEvent
                public static void onNamedClientTick(ClientTickEvent.Post tick) {
                    if (tick.phase == TickEvent.Phase.END && pending > 0) {
                        ping();
                    }
                }

                @SubscribeEvent
                public static void onLevelTick(LevelTickEvent.Post event) {
                    String textBlock = ${"\"\"\""}
                        LogicalSide.SERVER == event.side
                        event.side != LogicalSide.CLIENT
                        ${"\"\"\""};
                    // event.side == LogicalSide.SERVER
                    if (event.side == LogicalSide.SERVER) {
                        ping();
                    }
                }

                private static void use(LivingEntity entity) {}
                private static void ping() {}
            }
        """.trimIndent())

        val pass = StructuralRefactorPass()
        val result = pass.apply(projectDir)
        val migrated = tempDir.resolve("src/main/java/com/example/TickHandlers.java").readText()

        assertTrue(result.changes.any { it.ruleId == "struct-legacy-tick-events" })
        assertTrue(migrated.contains("import net.neoforged.neoforge.event.tick.EntityTickEvent;"))
        assertTrue(migrated.contains("import net.neoforged.neoforge.event.tick.PlayerTickEvent;"))
        assertTrue(migrated.contains("public static void onLivingTick(EntityTickEvent.Post event)"))
        assertTrue(migrated.contains("if (!(event.getEntity() instanceof LivingEntity entity)) return;"))
        assertTrue(migrated.contains("public static void onCancelableLivingTick(EntityTickEvent.Pre event)"))
        assertTrue(migrated.contains("if (!event.isCanceled())"))
        assertTrue(migrated.contains("public static void onPlayerTick(PlayerTickEvent.Post event)"))
        assertTrue(migrated.contains("scheduler.tick(event.getEntity());"), migrated)
        assertTrue(migrated.contains("""String playerTickDoc = "scheduler.tick(player);";"""), migrated)
        assertTrue(migrated.contains("scheduler.tick(player);\n            \"\"\";"), migrated)
        assertTrue(migrated.contains("// scheduler.tick(player);"), migrated)
        assertTrue(migrated.contains("if (pending <= 0) {"))
        assertTrue(migrated.contains("public static void onNamedClientTick(ClientTickEvent.Post tick)"))
        assertTrue(migrated.contains("if (pending > 0) {"))
        assertTrue(migrated.contains("if (!event.getLevel().isClientSide()) {"))
        assertTrue(!migrated.contains("LivingEvent.LivingTickEvent"))
        assertTrue(!migrated.contains("TickEvent.Phase"))
        assertTrue(!migrated.contains("event.phase"))
        assertTrue(!migrated.contains("tick.phase"))
        assertFalse(migrated.contains("import net.neoforged.fml.LogicalSide;"), migrated)
        assertFalse(migrated.contains("if (event.side == LogicalSide.SERVER) {"), migrated)
        assertTrue(migrated.contains("private static final String SIDE_DOC = \"event.side == LogicalSide.SERVER\";"), migrated)
        assertTrue(migrated.contains("LogicalSide.SERVER == event.side"), migrated)
        assertTrue(migrated.contains("event.side != LogicalSide.CLIENT"), migrated)
        assertTrue(migrated.contains("// event.side == LogicalSide.SERVER"), migrated)
        assertTrue(!migrated.contains("phase check removed"), migrated)
    }

