    @Test
    fun `migrates AbstractClientPlayer cape texture injections to PlayerSkin wrap`() {
        val projectDir = createFile("AbstractClientPlayerMixin.java", """
            package com.example.mixin;

            import com.example.EquipmentUtil;
            import com.example.Hooks;
            import com.example.SlotResult;
            import net.minecraft.client.player.AbstractClientPlayer;
            import net.minecraft.resources.ResourceLocation;
            import org.spongepowered.asm.mixin.Mixin;
            import org.spongepowered.asm.mixin.injection.At;
            import org.spongepowered.asm.mixin.injection.Inject;
            import org.spongepowered.asm.mixin.injection.callback.CallbackInfoReturnable;

            @Mixin(AbstractClientPlayer.class)
            public class AbstractClientPlayerMixin {
                @Inject(at = @At("HEAD"), method = "isCapeLoaded()Z", cancellable = true)
                private void isCapeLoaded(CallbackInfoReturnable<Boolean> cir) {
                    AbstractClientPlayer player = (AbstractClientPlayer) (Object) this;
                    if (EquipmentUtil.hasCape(player) && Hooks.isCapeVisible(player)) {
                        cir.setReturnValue(true);
                    }
                }

                @Inject(at = @At("HEAD"), method = "getCloakTextureLocation()Lnet/minecraft/resources/ResourceLocation;", cancellable = true)
                private void getCloakTextureLocation(CallbackInfoReturnable<ResourceLocation> cir) {
                    AbstractClientPlayer player = (AbstractClientPlayer) (Object) this;
                    SlotResult result = EquipmentUtil.getCape(player);
                    if (result != null && Hooks.isCapeVisible(player)) {
                        ResourceLocation texture = Hooks.getCapeTexture(result.stack());
                        if (texture != null) {
                            cir.setReturnValue(texture);
                        }
                    }
                }
            }
        """.trimIndent())

        val result = StructuralRefactorPass().apply(projectDir)
        val transformed = tempDir.resolve("src/main/java/com/example/AbstractClientPlayerMixin.java").readText()

        assertTrue(result.changes.any { it.ruleId == "struct-abstract-client-player-skin-wrap" }, "changes=${result.changes}")
        assertTrue(transformed.contains("import com.llamalad7.mixinextras.injector.wrapmethod.WrapMethod;"), transformed)
        assertTrue(transformed.contains("import com.llamalad7.mixinextras.injector.wrapoperation.Operation;"), transformed)
        assertTrue(transformed.contains("import net.minecraft.client.resources.PlayerSkin;"), transformed)
        assertTrue(transformed.contains("@WrapMethod(method = \"getSkin()Lnet/minecraft/client/resources/PlayerSkin;\")"), transformed)
        assertTrue(transformed.contains("private PlayerSkin getSkin(Operation<PlayerSkin> original)"), transformed)
        assertTrue(transformed.contains("PlayerSkin skin = original.call();"), transformed)
        assertTrue(transformed.contains("SlotResult result = EquipmentUtil.getCape(player);"), transformed)
        assertTrue(transformed.contains("if (result != null && Hooks.isCapeVisible(player))"), transformed)
        assertTrue(transformed.contains("return new PlayerSkin(skin.texture(), skin.textureUrl(), texture, skin.elytraTexture(), skin.model(), skin.secure());"), transformed)
        assertTrue(transformed.contains("return skin;"), transformed)
        assertFalse(transformed.contains("isCapeLoaded()Z"), transformed)
        assertFalse(transformed.contains("getCloakTextureLocation()"), transformed)
        assertFalse(transformed.contains("CallbackInfoReturnable"), transformed)
        assertFalse(transformed.contains("@Inject"), transformed)
        assertFalse(transformed.contains("org.spongepowered.asm.mixin.injection.At"), transformed)
    }

    @Test
    fun `migrates level storage load summaries lambda mixin descriptor`() {
        val projectDir = createFile("LevelStorageSourceMixin.java", """
            package com.example.mixin;

            import com.example.WorldDisplayHooks;
            import com.llamalad7.mixinextras.injector.wrapoperation.Operation;
            import com.llamalad7.mixinextras.injector.wrapoperation.WrapOperation;
            import com.llamalad7.mixinextras.sugar.Local;
            import net.minecraft.world.level.storage.LevelStorageSource;
            import org.spongepowered.asm.mixin.Mixin;
            import org.spongepowered.asm.mixin.injection.At;

            import java.nio.file.Path;

            @Mixin(LevelStorageSource.class)
            public class LevelStorageSourceMixin {
                @WrapOperation(method = { "lambda${'$'}loadLevelSummaries${'$'}2(Lnet/minecraft/world/level/storage/LevelStorageSource${'$'}LevelDirectory;)Lnet/minecraft/world/level/storage/LevelSummary;" }, at = @At(value = "INVOKE", target = "Lnet/minecraft/util/DirectoryLock;isLocked(Ljava/nio/file/Path;)Z"), require = 1, allow = 1)
                private boolean loadLevelSummaries(Path flag, Operation<Boolean> original, @Local(argsOnly = true) LevelStorageSource.LevelDirectory levelDirectory) {
                    if (WorldDisplayHooks.canUnlockLevel(levelDirectory.path())) {
                        return false;
                    }
                    return original.call(flag);
                }
            }
        """.trimIndent())

        val result = StructuralRefactorPass().apply(projectDir)
        val transformed = tempDir.resolve("src/main/java/com/example/LevelStorageSourceMixin.java").readText()

        assertTrue(result.changes.any { it.ruleId == "struct-vanilla-121-api" })
        assertTrue(transformed.contains("lambda${'$'}loadLevelSummaries${'$'}3(Lnet/minecraft/world/level/storage/LevelStorageSource${'$'}LevelDirectory;)Lnet/minecraft/world/level/storage/LevelSummary;"), transformed)
        assertFalse(transformed.contains("lambda${'$'}loadLevelSummaries${'$'}2"), transformed)
        assertTrue(transformed.contains("require = 1, allow = 1"), transformed)
    }

    @Test
    fun `migrates legacy mmlib datagen helpers without disabling providers`() {
        val srcDir = tempDir.resolve("src/main/java/com/example")
        srcDir.createDirectories()
        srcDir.resolve("SakuraBlockStateProvider.java").writeText("""
            package com.example;

            import cn.mcmod_mmf.mmlib.data.AbstractBlockStateProvider;
            import net.minecraft.data.PackOutput;
            import net.minecraft.resources.ResourceLocation;
            import net.minecraft.world.level.block.Block;
            import net.minecraft.world.level.block.SlabBlock;
            import net.minecraft.world.level.block.state.properties.BlockStateProperties;
            import net.neoforged.neoforge.common.data.ExistingFileHelper;

            public class SakuraBlockStateProvider extends AbstractBlockStateProvider {
                public SakuraBlockStateProvider(PackOutput out, String modid, ExistingFileHelper helper) {
                    super(out, modid, helper);
                }

                @Override
                protected void registerStatesAndModels() {
                    log(BlockRegistry.SAKURA_LOG);
                    crossBlock(BlockRegistry.SAKURA_SAPLING);
                    stageBlock(BlockRegistry.BUCKWHEAT_CROP, BlockStateProperties.AGE_7);
                    facingSlabBlock(BlockRegistry.TATAMI_SLAB, texture("tatami"), texture("tatami"), texture("tatami"));
                }
            }
        """.trimIndent())
        srcDir.resolve("SakuraItemModelProvider.java").writeText("""
            package com.example;

            import cn.mcmod_mmf.mmlib.data.AbstractItemModelProvider;
            import net.minecraft.data.PackOutput;
            import net.minecraft.world.item.BlockItem;
            import net.minecraft.world.level.block.BushBlock;
            import net.neoforged.neoforge.common.data.ExistingFileHelper;

            public class SakuraItemModelProvider extends AbstractItemModelProvider {
                public SakuraItemModelProvider(PackOutput out, String modid, ExistingFileHelper helper) {
                    super(out, modid, helper);
                }

                @Override
                protected void registerModels() {
                    BlockItem blockItem = (BlockItem) item.get();
                    if (blockItem.getBlock() instanceof BushBlock)
                        bushItem(item);
                    else
                        itemBlock(blockItem::getBlock);
                    normalItem(item);
                }
            }
        """.trimIndent())

        val pass = StructuralRefactorPass()
        val result = pass.apply(tempDir)
        val blockProvider = srcDir.resolve("SakuraBlockStateProvider.java").readText()
        val itemProvider = srcDir.resolve("SakuraItemModelProvider.java").readText()

        assertTrue(result.changes.any { it.ruleId == "struct-vanilla-121-api" })
        assertTrue(blockProvider.contains("import java.util.function.Supplier;"))
        assertTrue(blockProvider.contains("log(BlockRegistry.SAKURA_LOG::get);"))
        assertTrue(blockProvider.contains("crossBlock(BlockRegistry.SAKURA_SAPLING::get);"))
        assertTrue(blockProvider.contains("stageBlock(BlockRegistry.BUCKWHEAT_CROP::get, BlockStateProperties.AGE_7);"))
        assertTrue(blockProvider.contains("facingSlabBlock(BlockRegistry.TATAMI_SLAB::get, texture(\"tatami\"), texture(\"tatami\"), texture(\"tatami\"));"))
        assertTrue(blockProvider.contains("private void stageBlock(Supplier<? extends Block> blockSupplier, IntegerProperty ageProperty, Property<?>... ignored)"))
        assertTrue(blockProvider.contains("models().crop(modelName, texture(modelName))"))
        assertTrue(blockProvider.contains("private void facingSlabBlock(Supplier<? extends SlabBlock> slabSupplier"))
        assertTrue(blockProvider.contains("cn.mcmod_mmf.mmlib.block.FacingSlab.FACING"))
        assertTrue(itemProvider.contains("itemBlockFlat(() -> blockItem.getBlock());"))
        assertTrue(itemProvider.contains("toBlock(() -> blockItem.getBlock());"))
        assertTrue(itemProvider.contains("singleTex(item);"))
        assertTrue(!itemProvider.contains("bushItem(item);"))
        assertTrue(!itemProvider.contains("normalItem(item);"))
    }

