                /*
                boolean docs(ItemStack stack, CompoundTag tag) {
                    return PotionUtils.getPotion(stack) != Potions.EMPTY
                        || tag.getString("Potion").equals(Potions.EMPTY.toString());
                }
                */

                boolean real(ItemStack stack, CompoundTag tag) {
