    @Test
    fun `migrates cached check container recipes to single stack recipe holders`() {
        val srcDir = tempDir.resolve("src/main/java/com/example")
        srcDir.createDirectories()
        srcDir.resolve("IncubatorBlockEntity.java").writeText("""
            package com.example;

            import it.unimi.dsi.fastutil.objects.Object2IntOpenHashMap;
            import net.minecraft.core.NonNullList;
            import net.minecraft.resources.ResourceLocation;
            import net.minecraft.world.Container;
            import net.minecraft.world.entity.player.Player;
            import net.minecraft.world.inventory.RecipeCraftingHolder;
            import net.minecraft.world.item.ItemStack;
            import net.minecraft.world.item.crafting.Recipe;
            import net.minecraft.world.item.crafting.RecipeManager;
            import net.minecraft.world.item.crafting.RecipeType;
            import net.minecraft.world.level.Level;
            import javax.annotation.Nullable;
            import java.util.List;

            public class IncubatorBlockEntity implements Container, RecipeCraftingHolder {
                private final Object2IntOpenHashMap<ResourceLocation> recipesUsed = new Object2IntOpenHashMap<>();
                private final RecipeManager.CachedCheck<Container, IncubationRecipe> quickCheck;
                private NonNullList<ItemStack> items = NonNullList.withSize(2, ItemStack.EMPTY);

                public IncubatorBlockEntity(RecipeType<IncubationRecipe> recipeType) {
                    this.quickCheck = RecipeManager.createCheck(recipeType);
                }

                public static void serverTick(Level level, IncubatorBlockEntity blockEntity) {
                    IncubationRecipe recipe;
                    if (!blockEntity.items.get(0).isEmpty()) {
                        recipe = blockEntity.quickCheck.getRecipeFor(blockEntity, level).orElse(null);
                    } else {
                        recipe = null;
                    }
                    if (blockEntity.canIncubate(recipe, blockEntity.items)) {
                        if (blockEntity.incubate(recipe, blockEntity.items)) {
                            blockEntity.setRecipeUsed(recipe);
                        }
                    }
                }

                private boolean incubate(@Nullable IncubationRecipe recipe, NonNullList<ItemStack> stacks) {
                    return recipe != null && recipe.getEntity() != null && recipe.getTag() != null;
                }

                private boolean canIncubate(@Nullable IncubationRecipe recipe, NonNullList<ItemStack> stacks) {
                    return !stacks.get(0).isEmpty() && recipe != null;
                }

                private static int getTotalIncubationTime(Level level, IncubatorBlockEntity blockEntity) {
                    return blockEntity.quickCheck.getRecipeFor(blockEntity, level).map(IncubationRecipe::getIncubationTime).orElse(5700);
                }

                @Override
                public void setRecipeUsed(@Nullable Recipe<?> recipe) {
                    if (recipe != null) {
                        ResourceLocation resourcelocation = recipe.getId();
                        this.recipesUsed.addTo(resourcelocation, 1);
                    }
                }

                @Nullable
                @Override
                public Recipe<?> getRecipeUsed() {
                    return null;
                }

                @Override
                public void awardUsedRecipes(Player player, List<ItemStack> items) {}
            }
        """.trimIndent())
        srcDir.resolve("ItemStackTags.java").writeText("""
            package com.example;

            import net.minecraft.nbt.CompoundTag;
            import net.minecraft.world.item.ItemStack;

            public class ItemStackTags {
                CompoundTag stackTag(ItemStack stack, IncubationRecipe recipe) {
                    CompoundTag fromStack = stack.getTag();
                    CompoundTag fromRecipe = recipe.getTag();
                    return fromRecipe == null ? fromStack : fromRecipe;
                }
            }
        """.trimIndent())

        val result = StructuralRefactorPass().apply(tempDir)
        val blockEntity = srcDir.resolve("IncubatorBlockEntity.java").readText()
        val tags = srcDir.resolve("ItemStackTags.java").readText()

        assertTrue(result.changes.any { it.ruleId == "struct-vanilla-121-api" })
        assertTrue(blockEntity.contains("RecipeManager.CachedCheck<SingleRecipeInput, IncubationRecipe> quickCheck"), blockEntity)
        assertTrue(blockEntity.contains("RecipeHolder<IncubationRecipe> recipe;"), blockEntity)
        assertTrue(blockEntity.contains("quickCheck.getRecipeFor(new SingleRecipeInput(blockEntity.getItem(0)), level).orElse(null)"), blockEntity)
        assertTrue(blockEntity.contains("private boolean incubate(@Nullable RecipeHolder<IncubationRecipe> recipe"), blockEntity)
        assertTrue(blockEntity.contains("recipe.value().getEntity()"), blockEntity)
        assertTrue(blockEntity.contains("recipe.value().getTag()"), blockEntity)
        assertTrue(blockEntity.contains("map(RecipeHolder::value).map(IncubationRecipe::getIncubationTime)"), blockEntity)
        assertTrue(blockEntity.contains("setRecipeUsed(@Nullable RecipeHolder<?> recipe)"), blockEntity)
        assertTrue(blockEntity.contains("ResourceLocation resourcelocation = recipe.id();"), blockEntity)
        assertTrue(blockEntity.contains("public RecipeHolder<?> getRecipeUsed()"), blockEntity)
        assertTrue(blockEntity.contains("import net.minecraft.world.item.crafting.RecipeHolder;"), blockEntity)
        assertTrue(blockEntity.contains("import net.minecraft.world.item.crafting.SingleRecipeInput;"), blockEntity)
        assertFalse(blockEntity.contains("CachedCheck<Container"), blockEntity)
        assertTrue(tags.contains("stack.getOrDefault(net.minecraft.core.component.DataComponents.CUSTOM_DATA, net.minecraft.world.item.component.CustomData.EMPTY).copyTag()"), tags)
        assertTrue(tags.contains("CompoundTag fromRecipe = recipe.getTag();"), tags)
    }

    @Test
    fun `migrates furnace quick check accessors to recipe holder single stack boundaries`() {
        val srcDir = tempDir.resolve("src/main/java/com/example")
        val accessorDir = srcDir.resolve("mixin")
        srcDir.createDirectories()
        accessorDir.createDirectories()
        accessorDir.resolve("AbstractFurnaceBlockEntityAccessor.java").writeText("""
            package com.example.mixin;

            import net.minecraft.core.NonNullList;
            import net.minecraft.core.RegistryAccess;
            import net.minecraft.world.Container;
            import net.minecraft.world.item.ItemStack;
            import net.minecraft.world.item.crafting.AbstractCookingRecipe;
            import net.minecraft.world.item.crafting.Recipe;
            import net.minecraft.world.item.crafting.RecipeManager;
            import net.minecraft.world.level.block.entity.AbstractFurnaceBlockEntity;
            import org.spongepowered.asm.mixin.Mixin;
            import org.spongepowered.asm.mixin.gen.Accessor;
            import org.spongepowered.asm.mixin.gen.Invoker;
            import javax.annotation.Nullable;

            @Mixin(AbstractFurnaceBlockEntity.class)
            public interface AbstractFurnaceBlockEntityAccessor {
                @Accessor("quickCheck")
                RecipeManager.CachedCheck<Container, ? extends AbstractCookingRecipe> example${'$'}getQuickCheck();

                @Invoker
                boolean callCanBurn(RegistryAccess registryAccess, @Nullable Recipe<?> recipe, NonNullList<ItemStack> stacks, int stackSize);

                @Accessor("items")
                NonNullList<ItemStack> example${'$'}getItems();
            }
        """.trimIndent())
        srcDir.resolve("FurnaceHookBlockEntity.java").writeText("""
            package com.example;

            import com.example.mixin.AbstractFurnaceBlockEntityAccessor;
            import net.minecraft.core.NonNullList;
            import net.minecraft.core.RegistryAccess;
            import net.minecraft.world.WorldlyContainer;
            import net.minecraft.world.item.ItemStack;
            import net.minecraft.world.item.crafting.AbstractCookingRecipe;
            import net.minecraft.world.item.crafting.Ingredient;
            import net.minecraft.world.item.crafting.Recipe;
            import net.minecraft.world.item.enchantment.EnchantmentHelper;
            import net.minecraft.world.level.Level;
            import net.minecraft.world.level.block.entity.AbstractFurnaceBlockEntity;
            import javax.annotation.Nullable;
            import java.util.Optional;

            public class FurnaceHookBlockEntity extends AbstractFurnaceBlockEntity {
                public static void tick(Level level, FurnaceHookBlockEntity blockEntity) {
                    AbstractFurnaceBlockEntityAccessor accessor = (AbstractFurnaceBlockEntityAccessor) blockEntity;
                    Recipe<?> recipe;
                    if (!accessor.example${'$'}getItems().get(0).isEmpty()) {
                        recipe = accessor.example${'$'}getQuickCheck().getRecipeFor(blockEntity, level).orElse(null);
                    } else {
                        recipe = null;
                    }
                    int maxStackSize = blockEntity.getMaxStackSize();
                    if (accessor.callCanBurn(level.registryAccess(), recipe, accessor.example${'$'}getItems(), maxStackSize)) {
                        if (blockEntity.burn(level.registryAccess(), recipe, accessor.example${'$'}getItems(), maxStackSize)) {
                            blockEntity.setRecipeUsed(recipe);
                        }
                    }
                }

                @SuppressWarnings("unchecked")
                private boolean burn(RegistryAccess registryAccess, @Nullable Recipe<?> recipe, NonNullList<ItemStack> stacks, int stackSize) {
                    AbstractFurnaceBlockEntityAccessor accessor = (AbstractFurnaceBlockEntityAccessor) this;
                    if (recipe != null && accessor.callCanBurn(registryAccess, recipe, stacks, stackSize)) {
                        ItemStack inputSlotStack = stacks.get(0);
                        ItemStack resultStack = ((Recipe<WorldlyContainer>) recipe).assemble(this, registryAccess);
                        EnchantmentHelper.setEnchantments(EnchantmentHelper.getEnchantments(inputSlotStack), resultStack);
                        EnchantmentHelper.setEnchantments(EnchantmentHelper.getEnchantments(this.getItem(1)), resultStack);
                    }
                    return true;
                }

                public boolean canTakeItemThroughFace(int index, ItemStack stack) {
                    AbstractFurnaceBlockEntityAccessor accessor = (AbstractFurnaceBlockEntityAccessor) this;
                    Optional<NonNullList<Ingredient>> ingredient = accessor.example${'$'}getQuickCheck().getRecipeFor(this, this.level).map(AbstractCookingRecipe::getIngredients);
                    return ingredient.isPresent();
                }
            }
        """.trimIndent())

        StructuralRefactorPass().apply(tempDir)
        val accessor = accessorDir.resolve("AbstractFurnaceBlockEntityAccessor.java").readText()
        val blockEntity = srcDir.resolve("FurnaceHookBlockEntity.java").readText()

        assertTrue(accessor.contains("RecipeManager.CachedCheck<SingleRecipeInput, ? extends AbstractCookingRecipe> example${'$'}getQuickCheck()"), accessor)
        assertTrue(accessor.contains("static boolean callCanBurn(RegistryAccess registryAccess, @Nullable RecipeHolder<?> recipe, NonNullList<ItemStack> stacks, int stackSize, AbstractFurnaceBlockEntity furnace)"), accessor)
        assertTrue(accessor.contains("throw new AssertionError();"), accessor)
        assertTrue(blockEntity.contains("RecipeHolder<?> recipe;"), blockEntity)
        assertTrue(blockEntity.contains("example${'$'}getQuickCheck().getRecipeFor(new SingleRecipeInput(blockEntity.getItem(0)), level).orElse(null)"), blockEntity)
        assertTrue(blockEntity.contains("AbstractFurnaceBlockEntityAccessor.callCanBurn(level.registryAccess(), recipe, accessor.example${'$'}getItems(), maxStackSize, blockEntity)"), blockEntity)
        assertTrue(blockEntity.contains("private boolean burn(RegistryAccess registryAccess, @Nullable RecipeHolder<?> recipe"), blockEntity)
        assertTrue(blockEntity.contains("AbstractFurnaceBlockEntityAccessor.callCanBurn(registryAccess, recipe, stacks, stackSize, this)"), blockEntity)
        assertTrue(blockEntity.contains("((Recipe<SingleRecipeInput>) recipe.value()).assemble(new SingleRecipeInput(inputSlotStack), registryAccess)"), blockEntity)
        assertTrue(blockEntity.contains(".map(RecipeHolder::value).map(AbstractCookingRecipe::getIngredients)"), blockEntity)
        assertTrue(blockEntity.contains("EnchantmentHelper.setEnchantments(resultStack, EnchantmentHelper.getEnchantmentsForCrafting(inputSlotStack))"), blockEntity)
        assertTrue(blockEntity.contains("EnchantmentHelper.setEnchantments(resultStack, EnchantmentHelper.getEnchantmentsForCrafting(this.getItem(1)))"), blockEntity)
        assertFalse(accessor.contains("CachedCheck<Container"), accessor)
        assertFalse(blockEntity.contains("accessor.callCanBurn"), blockEntity)
        assertFalse(blockEntity.contains("Recipe<WorldlyContainer>"), blockEntity)
    }

