        assertTrue(preview.contains("(float) Math.atan((double) (((float) (x + 31) - mouseX) / 40.0F))"), preview)
        assertTrue(preview.contains("(float) Math.atan((double) (((float) (y + 25) - mouseY) / 40.0F))"), preview)
