    @Test
    fun `legacy mob custom damage source attack migration uses executable doHurtTarget evidence`() {
        val srcDir = tempDir.resolve("src/main/java/com/example")
        srcDir.createDirectories()
        srcDir.resolve("AttackDocsMob.java").writeText("""
            package com.example;

            import net.minecraft.world.entity.Entity;
            import net.minecraft.world.entity.EntityType;
            import net.minecraft.world.entity.LivingEntity;
            import net.minecraft.world.entity.Mob;
            import net.minecraft.world.entity.ai.attributes.Attributes;
            import net.minecraft.world.entity.player.Player;
            import net.minecraft.world.item.ItemStack;
            import net.minecraft.world.item.enchantment.EnchantmentHelper;
            import net.minecraft.world.level.Level;

            public class AttackDocsMob extends Mob {
                /*
                public boolean doHurtTarget(Entity fake) {
                    float f = (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE);
                    float f1 = (float) this.getAttributeValue(Attributes.ATTACK_KNOCKBACK);
                    if (fake instanceof LivingEntity living) {
                        f += EnchantmentHelper.getDamageBonus(this.getMainHandItem(), living.getMobType());
                        f1 += (float) EnchantmentHelper.getKnockbackBonus(this);
                    }
                    int i = EnchantmentHelper.getFireAspect(this);
                    if (i > 0) {
                        fake.igniteForSeconds(i * 4);
                    }
                    boolean flag = fake.hurt(this.damageSources().mobAttack(this), f);
                    if (flag) {
                        this.doEnchantDamageEffects(this, fake);
                    }
                    return flag;
                }
                */
                private static final String DOC = "public boolean doHurtTarget(Entity fake)";

                public AttackDocsMob(EntityType<? extends Mob> type, Level level) {
                    super(type, level);
                }

                @Override
                public boolean doHurtTarget(Entity entity) {
                    float f = (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE);
                    float f1 = (float) this.getAttributeValue(Attributes.ATTACK_KNOCKBACK);
                    if (entity instanceof LivingEntity living) {
                        f += EnchantmentHelper.getDamageBonus(this.getMainHandItem(), living.getMobType());
                        f1 += (float) EnchantmentHelper.getKnockbackBonus(this);
                    }

                    int i = EnchantmentHelper.getFireAspect(this);
                    if (i > 0) {
                        entity.igniteForSeconds(i * 4);
                    }

                    boolean flag = entity.hurt(this.damageSources().mobAttack(this), f);
                    if (flag) {
                        if (f1 > 0.0F && entity instanceof LivingEntity living) {
                            living.knockback(f1 * 0.5F, net.minecraft.util.Mth.sin(this.getYRot() * net.minecraft.util.Mth.DEG_TO_RAD), -net.minecraft.util.Mth.cos(this.getYRot() * net.minecraft.util.Mth.DEG_TO_RAD));
                        }

                        if (entity instanceof Player player) {
                            this.maybeDisableShield(player, this.getMainHandItem(), player.isUsingItem() ? player.getUseItem() : ItemStack.EMPTY);
                        }

                        this.doEnchantDamageEffects(this, entity);
                        this.setLastHurtMob(entity);
                    }

                    return flag;
                }

                public void after() {
                }
            }
        """.trimIndent())

        val result = StructuralRefactorPass().apply(tempDir)
        val migrated = srcDir.resolve("AttackDocsMob.java").readText()
        val realMethod = migrated.substring(
            migrated.indexOf("@Override"),
            migrated.indexOf("public void after")
        )

        assertTrue(result.errors.isEmpty(), "errors=${result.errors}")
        assertTrue(migrated.contains("import net.minecraft.world.damagesource.DamageSource;"), migrated)
        assertTrue(migrated.contains("import net.minecraft.server.level.ServerLevel;"), migrated)
        assertTrue(realMethod.contains("DamageSource damagesource = this.damageSources().mobAttack(this);"), realMethod)
        assertTrue(realMethod.contains("boolean flag = entity.hurt(damagesource, f);"), realMethod)
        assertTrue(realMethod.contains("float f1 = this.getKnockback(entity, damagesource);"), realMethod)
        assertTrue(realMethod.contains("EnchantmentHelper.doPostAttackEffects(serverlevel1, entity, damagesource);"), realMethod)
        assertFalse(realMethod.contains("getDamageBonus"), realMethod)
        assertFalse(realMethod.contains("getKnockbackBonus"), realMethod)
        assertFalse(realMethod.contains("getFireAspect"), realMethod)
        assertFalse(realMethod.contains("maybeDisableShield"), realMethod)
        assertFalse(realMethod.contains("doEnchantDamageEffects(this, entity)"), realMethod)
        assertTrue(migrated.contains("public boolean doHurtTarget(Entity fake)"), migrated)
        assertTrue(migrated.contains("private static final String DOC = \"public boolean doHurtTarget(Entity fake)\";"), migrated)
    }

    @Test
    fun `migrates crafting menu recipe holder and input boundaries`() {
        val srcDir = tempDir.resolve("src/main/java/com/example")
        srcDir.createDirectories()
        srcDir.resolve("CraftingMenuSurface.java").writeText("""
            package com.example;

            import java.util.Optional;
            import net.minecraft.network.protocol.game.ClientboundContainerSetSlotPacket;
            import net.minecraft.server.MinecraftServer;
            import net.minecraft.server.level.ServerPlayer;
            import net.minecraft.world.Container;
            import net.minecraft.world.entity.player.Player;
            import net.minecraft.world.inventory.CraftingContainer;
            import net.minecraft.world.inventory.RecipeBookMenu;
            import net.minecraft.world.inventory.ResultContainer;
            import net.minecraft.world.inventory.TransientCraftingContainer;
            import net.minecraft.world.item.ItemStack;
            import net.minecraft.world.item.crafting.CraftingRecipe;
            import net.minecraft.world.item.crafting.Recipe;
            import net.minecraft.world.item.crafting.RecipeHolder;
            import net.minecraft.world.item.crafting.RecipeType;

            public abstract class CraftingMenuSurface extends RecipeBookMenu<CraftingContainer> {
                private final Player player;
                private final CraftingContainer craftMatrix = new TransientCraftingContainer(this, 2, 2);
                private final ResultContainer craftResult = new ResultContainer();

                @Override
                public boolean recipeMatches(Recipe<? super CraftingContainer> recipe) {
                    return recipe.matches(this.craftMatrix, this.player.level());
                }

                public void slotsChanged(Container container) {
                    MinecraftServer server = this.player.level().getServer();
                    if (server == null) return;
                    Optional<RecipeHolder<CraftingRecipe>> recipe = server.getRecipeManager().getRecipeFor(RecipeType.CRAFTING, this.craftMatrix, this.player.level());
                    if (recipe.isPresent()) {
                        ServerPlayer playerMP = (ServerPlayer) this.player;
                        ItemStack itemStack = ItemStack.EMPTY;
                        CraftingRecipe craftingRecipe = recipe.get();
                        if (this.craftResult.setRecipeUsed(this.player.level(), playerMP, craftingRecipe)) {
                            itemStack = craftingRecipe.assemble(this.craftMatrix, this.player.level().registryAccess());
                        }
                        playerMP.connection.send(new ClientboundContainerSetSlotPacket(this.containerId, this.incrementStateId(), 0, itemStack));
                    }
                }
            }
        """.trimIndent())

        val result = StructuralRefactorPass().apply(tempDir)
        val transformed = srcDir.resolve("CraftingMenuSurface.java").readText()

        assertTrue(result.errors.isEmpty(), "errors=${result.errors}")
        assertTrue(transformed.contains("public boolean recipeMatches(RecipeHolder<CraftingRecipe> recipe)"), transformed)
        assertTrue(transformed.contains("return recipe.value().matches(this.craftMatrix.asCraftInput(), this.player.level());"), transformed)
        assertTrue(transformed.contains("getRecipeFor(RecipeType.CRAFTING, this.craftMatrix.asCraftInput(), this.player.level())"), transformed)
        assertTrue(transformed.contains("RecipeHolder<CraftingRecipe> craftingRecipeHolder = recipe.get();"), transformed)
        assertTrue(transformed.contains("CraftingRecipe craftingRecipe = craftingRecipeHolder.value();"), transformed)
        assertTrue(transformed.contains("setRecipeUsed(this.player.level(), playerMP, craftingRecipeHolder)"), transformed)
        assertTrue(transformed.contains("craftingRecipe.assemble(this.craftMatrix.asCraftInput(), this.player.level().registryAccess())"), transformed)
        assertTrue(transformed.contains("import net.minecraft.world.item.crafting.CraftingInput;"), transformed)
        assertFalse(transformed.contains("Recipe<? super CraftingContainer>"), transformed)
    }

    @Test
    fun `migrates entity additional save data provider delegates structurally`() {
        val srcDir = tempDir.resolve("src/main/java/com/example")
        srcDir.createDirectories()
        srcDir.resolve("AetherBossMob.java").writeText("""
            package com.example;

            import com.aetherteam.nitrogen.entity.BossMob;

            public interface AetherBossMob<T> extends BossMob<T> {
            }
        """.trimIndent())
        srcDir.resolve("BossEntity.java").writeText("""
            package com.example;

            import net.minecraft.network.RegistryFriendlyByteBuf;
            import net.minecraft.nbt.CompoundTag;
            import net.minecraft.world.entity.EntityType;
            import net.minecraft.world.entity.Mob;
            import net.minecraft.world.item.ItemStack;
            import net.minecraft.world.level.Level;

            public abstract class BossEntity extends Mob implements AetherBossMob<BossEntity> {
                private ItemStack stack;

                protected BossEntity(EntityType<? extends Mob> type, Level level) {
                    super(type, level);
                }

                @Override
                protected void addAdditionalSaveData(CompoundTag tag) {
                    super.addAdditionalSaveData(tag);
                    this.addBossSaveData(tag);
                    this.addLocalSaveData(tag);
                    tag.put("Stack", this.stack.save());
                }

                @Override
                protected void readAdditionalSaveData(CompoundTag tag) {
                    super.readAdditionalSaveData(tag);
                    this.readBossSaveData(tag);
                    this.readLocalSaveData(tag);
                    this.stack = ItemStack.of(tag.getCompound("Stack"));
                }

                public void writeSpawnData(RegistryFriendlyByteBuf buffer) {
                    CompoundTag spawnTag = new CompoundTag();
                    this.addBossSaveData(spawnTag);
                    buffer.writeNbt(spawnTag);
                }

                public void readSpawnData(RegistryFriendlyByteBuf data) {
                    CompoundTag spawnTag = data.readNbt();
                    if (spawnTag != null) {
                        this.readBossSaveData(spawnTag);
                    }
                }

                private void addLocalSaveData(CompoundTag tag) {
                }

                private void readLocalSaveData(CompoundTag tag) {
                }
            }
        """.trimIndent())

        val result = StructuralRefactorPass().apply(tempDir)
        val boss = srcDir.resolve("BossEntity.java").readText()

        assertTrue(result.errors.isEmpty(), "errors=${result.errors}")
        assertTrue(boss.contains("protected void addAdditionalSaveData(CompoundTag tag)"), boss)
        assertTrue(boss.contains("protected void readAdditionalSaveData(CompoundTag tag)"), boss)
        assertTrue(boss.contains("super.addAdditionalSaveData(tag);"), boss)
        assertTrue(boss.contains("this.addBossSaveData(tag, this.registryAccess());"), boss)
        assertTrue(boss.contains("super.readAdditionalSaveData(tag);"), boss)
        assertTrue(boss.contains("this.readBossSaveData(tag, this.registryAccess());"), boss)
        assertTrue(boss.contains("tag.put(\"Stack\", this.stack.save(this.registryAccess()));"), boss)
        assertTrue(boss.contains("this.stack = ItemStack.parseOptional(this.registryAccess(), tag.getCompound(\"Stack\"));"), boss)
        assertTrue(boss.contains("this.addBossSaveData(spawnTag, this.registryAccess());"), boss)
        assertTrue(boss.contains("this.readBossSaveData(spawnTag, this.registryAccess());"), boss)
        assertTrue(boss.contains("this.addLocalSaveData(tag);"), boss)
        assertTrue(boss.contains("this.readLocalSaveData(tag);"), boss)
    }

