        assertTrue(categories.contains("MobCategory.valueOf(\"EXAMPLEMOD_SKY_MONSTER\")"))
        assertTrue(categories.contains("MobCategory.valueOf(\"EXAMPLEMOD_AERWHALE\")"))
        assertFalse(categories.contains("MobCategory.create("))
        assertTrue(helper.contains("public static Object MobCategory_EXAMPLEMOD_SKY_MONSTER(int idx, Class<?> type)"))
        assertFalse(helper.contains("type.cast("), helper)
        assertTrue(helper.contains("case 0 -> \"examplemod:sky_monster\";"))
        assertTrue(helper.contains("case 0 -> \"examplemod:aerwhale\";"))
        assertTrue(helper.contains("case 1 -> 4;"))
        assertTrue(helper.contains("case 2 -> false;"))
        assertTrue(helper.contains("case 3 -> false;"))
        assertTrue(helper.contains("case 4 -> 128;"))
        assertTrue(enumExtensions.contains("\"enum\": \"net/minecraft/world/entity/MobCategory\""))
        assertTrue(enumExtensions.contains("\"constructor\": \"(Ljava/lang/String;IZZI)V\""))
        assertTrue(enumExtensions.contains("\"name\": \"EXAMPLEMOD_SKY_MONSTER\""))
        assertTrue(toml.contains("enumExtensions=\"META-INF/enumextensions.json\""))
        assertTrue(toml.indexOf("[[mods]]") < toml.indexOf("enumExtensions=\"META-INF/enumextensions.json\""), toml)
        assertTrue(toml.indexOf("enumExtensions=\"META-INF/enumextensions.json\"") < toml.indexOf("modId=\"examplemod\""), toml)
        assertTrue(result.changes.any { it.ruleId == "struct-mobcategory-data-keys" })
        assertTrue(biome.contains(""""examplemod:sky_monster": ["""), biome)
        assertTrue(biome.contains(""""examplemod:aerwhale": ["""), biome)
        assertTrue(biome.contains(""""sky_monster": "not a mob category key""""), biome)
        assertTrue(structure.contains(""""examplemod:sky_monster": {"""), structure)
        assertFalse(structure.contains(""""sky_monster": {"""), structure)
    }

    @Test
    fun `mob effect tick trailing return is added after nested lambda blocks`() {
        val srcDir = tempDir.resolve("src/main/java/com/example")
        srcDir.createDirectories()
        srcDir.resolve("RemedyEffect.java").writeText("""
            package com.example;

            import java.util.Optional;
            import net.minecraft.world.effect.MobEffect;
            import net.minecraft.world.effect.MobEffectCategory;
            import net.minecraft.world.entity.LivingEntity;

            public class RemedyEffect extends MobEffect {
                public RemedyEffect() {
                    super(MobEffectCategory.BENEFICIAL, 0x123456);
                }

                @Override
                public boolean applyEffectTick(LivingEntity livingEntity, int amplifier) {
                    Optional.of(livingEntity).ifPresent((entity) -> {
                        if (entity.isAlive()) {
                            entity.clearFire();
                        }
                    });
                    livingEntity.setTicksFrozen(0);
                }
            }
        """.trimIndent())

        val result = StructuralRefactorPass().apply(tempDir)
        val migrated = srcDir.resolve("RemedyEffect.java").readText()

        assertTrue(result.errors.isEmpty(), "errors=${result.errors}")
        assertTrue(Regex("""(?s)\}\);\s*livingEntity\.setTicksFrozen\(0\);\s*return true;\s*\}""").containsMatchIn(migrated), migrated)
        assertFalse(Regex("""(?s)ifPresent\s*\([^;]+return true;[^;]+;""").containsMatchIn(migrated), migrated)
    }

