        assertTrue(mixin.contains("if (target instanceof LivingEntity) {"), mixin)
        assertTrue(mixin.contains("Hooks.damageGloves(player);"), mixin)
        assertFalse(mixin.contains("EnchantmentHelper;doPostHurtEffects"), mixin)
    }

